import warnings
from fastapi.responses import ORJSONResponse, UJSONResponse
from fastapi.exceptions import FastAPIDeprecationWarning

def test_orjson_deprecation():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        try:
            ORJSONResponse({"foo": "bar"})
        except AssertionError:
            pass
        for warning in w:
            if issubclass(warning.category, FastAPIDeprecationWarning):
                print("Caught ORJSONResponse deprecation warning")
                return
    print("Failed to catch ORJSONResponse deprecation warning")
    exit(1)

def test_ujson_deprecation():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        try:
            UJSONResponse({"foo": "bar"})
        except AssertionError:
            pass
        for warning in w:
            if issubclass(warning.category, FastAPIDeprecationWarning):
                print("Caught UJSONResponse deprecation warning")
                return
    print("Failed to catch UJSONResponse deprecation warning")
    exit(1)

if __name__ == "__main__":
    test_orjson_deprecation()
    test_ujson_deprecation()
    print("All tests passed!")
